Lemma shadow_of_den : forall (A : atable) E M k b n sb sk sn, know_ok asegs E M k -> shadow_of A k b n = (sb, sk, sn) ->
  0 <= shadow_off A <= 2 ^ 47 -> 0 <= estart E (SA sb sk) < 2 ^ 64 ->
